from lib import *
S = SS('w73')
steps = [
    step("macOS 不读 /etc/resolv.conf 来决定怎么解析名字,而是看系统配置里的“解析器列表”(scutil --dns)。默认(非作用域)解析器共 7 个。1 号是主力:搜索域 lan,名字服务器 114.114.114.114 和 223.5.5.5(这份配置的来源我没有查),标志 “Request A records”(只请求 A 记录)。2~7 号都是 mDNS 解析器,各管一类名字:local(超时 5 秒)、254.169.in-addr.arpa(链路本地 IPv4 的反向解析),以及 8 / 9 / a / b.e.f.ip6.arpa(fe80::/10 链路本地 IPv6 的反向解析)。也就是说,什么名字交给谁,是按域名后缀选择解析器的。/etc/hosts 的文件头自己写着:它不被大多数进程用于 DNS 主机名解析——但 localhost 等少数条目仍然有效(第四节验证)。", t=tl(S(1)), mark=lidx(S(1), 'resolver #1', 'resolver #2'), done=lidx(S(1), 'resolver #3', 'resolver #7', '默认(非作用域)解析器共 7 个'), kv=KV([['1 号', 'search lan,114.114.114.114 / 223.5.5.5,Request A records'], ['2~7 号', 'mDNS:local 与链路本地反向域'], ['选择方式', '按名字的后缀挑解析器']], ['1 号'])),
    step("一次 getaddrinfo(\"w73-<随机>.example.com\")(名字里有点)在线路上发了什么(抓 en0)。要 IPv4 + IPv6(AF_UNSPEC)时,线上只有 2 个包:+0.0 ms 向第一个名字服务器 114.114.114.114 发一个 A 查询,+285.2 ms 收到响应 RCODE 3(NXDOMAIN),整个调用耗时 291 ms。没有 AAAA 查询!只要 IPv4(AF_INET)时同样只有一个 A 查询,259 ms。这是因为配置里的标志是 “Request A records”:这台机器没有可用的 IPv6 连接,系统干脆不问 AAAA(和第 26、27 篇里 getaddrinfo 只返回 IPv4 的现象一致)。也没有向第二个名字服务器 223.5.5.5 发任何东西,因为第一个已经给出了确定的回答(NXDOMAIN 不算失败)。", t=tl(S(2)), mark=lidx(S(2), 'AF_UNSPEC:耗时', 'AF_INET 时发出的查询类型'), done=lidx(S(2), '114.114.114.114      查询', '114.114.114.114      响应', '只要 IPv4'), b=bars([['AF_UNSPEC 耗时', 291, '291 ms'], ['AF_INET 耗时', 259, '259 ms']], 291, mark=[], done=[0, 1]), kv=KV([['AF_UNSPEC', '只发 A 查询 1 个'], ['AAAA', '没有发(配置标志 Request A records)'], ['第二个名字服务器', '没有用到']], ['AAAA'])),
    step("单标签名字(没有点)与搜索域。getaddrinfo(\"w73host<随机>\") 失败(Errno 8:nodename nor servname provided, or not known),耗时 55 ms,线上 4 个包,全部发给 114.114.114.114:+0.0 ms 先问 w73host<随机>.lan.(加上了搜索域 lan),+27.7 ms 收到 NXDOMAIN;+31.0 ms 再问不带后缀的裸名字 w73host<随机>.,+46.7 ms 又收到 NXDOMAIN。顺序是:先加搜索域,再试原名;所以内网里的短名字会先被当作 <名字>.lan 去问,失败了才问全局。两次都是 NXDOMAIN,都是同一个名字服务器回答。", t=tl(S(3)), mark=lidx(S(3), 'w73hostbdgchl.lan.', 'w73hostbdgchl.\'', '出现过的查询名字'), done=lidx(S(3), '耗时 55 ms', '这次查询发往的服务器'), kv=KV([['第一问', '<名字>.lan.(加搜索域)'], ['第二问', '<名字>.(裸名字)'], ['服务器', '都是 114.114.114.114'], ['总耗时', '55 ms,失败']], ['第一问'])),
    step("不走 DNS 的名字:localhost 解析成 127.0.0.1 和 ::1,耗时 0.8 ms,抓到 0 个 DNS / mDNS 包;broadcasthost 解析成 255.255.255.255,耗时 2.8 ms(抓到的 1 个包是本机别的进程发的 mDNS,不是这次解析的 DNS 查询)。这两个名字是 /etc/hosts 里的条目,系统直接在本地给出答案,不发 DNS 查询。我无法修改 /etc/hosts(没有 root),所以没有验证“往 /etc/hosts 里加一行任意名字是否生效”——文件头那句“不被大多数进程用于 DNS 主机名解析”对这类自定义条目是否成立,这里没有测。", t=tl(S(4)), mark=lidx(S(4), 'localhost', 'broadcasthost'), done=lidx(S(4), 'localhost'), kv=KV([['localhost', '127.0.0.1 + ::1,0.8 ms,0 个 DNS 包'], ['broadcasthost', '255.255.255.255,2.8 ms'], ['自定义条目', '没有测(无 root)']], ['localhost'])),
    step(".local 名字走 mDNS(多播)而不是上面的名字服务器。getaddrinfo(\"w73-<随机>.local\") 失败,耗时 5002 ms(正好是 scutil 里 local 解析器的 5 秒超时)。线上本机发出的 mDNS 查询:+0.0 ms、+1004.6 ms、+4012.0 ms 各发一次 w73-<随机>.local 的 A 查询(间隔 1 秒、3 秒,逐步退避),目的地是组播地址 224.0.0.251;期间 114.114.114.114 没有收到任何关于这个名字的 DNS 查询。+3723.7 ms 的那条是本机另一个进程发的服务发现查询,与这次解析无关。要点:.local 的名字查不到时,要白白等 5 秒——这也是第 35 篇里 Python 的 mDNS 要 5 秒超时的原因。", t=tl(S(5)), mark=lidx(S(5), 'getaddrinfo("w73-', '+ 1004.6 ms', '+ 4012.0 ms'), done=lidx(S(5), '按(类型, 目的地址)计数'), b=bars([['第 1 次 mDNS 查询', 0, '+0 ms'], ['第 2 次', 1004.6, '+1004.6 ms'], ['第 3 次', 4012.0, '+4012.0 ms'], ['getaddrinfo 超时', 5002, '5002 ms']], 5002, mark=[3], done=[0, 1, 2]), kv=KV([['.local', '多播 224.0.0.251'], ['查询时刻', '0 / 1.0 s / 4.0 s'], ['失败耗时', '5002 ms'], ['114.114.114.114', '没有收到这个名字']], ['失败耗时'])),
]
A = mkartw('w73', 73, '网络协议,DNS,getaddrinfo,存根解析器,搜索域,mDNS,/etc/hosts,真实验证,动画演示',
    '实测 macOS 怎么解析名字:按域名后缀在 7 个解析器里选(1 个单播、6 个 mDNS);AF_UNSPEC 也只发 A 查询(Request A records,没有 AAAA);单标签名字先加搜索域 lan 再问裸名字;localhost 不发 DNS;.local 走 224.0.0.251 的 mDNS,查不到要等 5002 ms。',
    '应用调用 getaddrinfo 之后,到底发生了什么?操作系统里的“存根解析器”按什么规则选名字服务器、要不要加搜索域、先查 /etc/hosts 还是先发 DNS、.local 为什么走多播?这篇用抓包把一次次 getaddrinfo 在线路上的真实动作逐个看清,并且只保留本机自己发出的包。',
    [('2 个包', '一次 getaddrinfo 在线路上的全部 DNS 流量:1 个 A 查询 + 1 个响应(没有 AAAA)'), ('lan. → 裸名', '单标签名字先加搜索域再问原名的顺序'), ('5002 ms', '.local 名字解析失败所需时间,等 mDNS 超时')],
    [('解析器列表', '<p>macOS 按系统配置里的 7 个解析器按后缀选择:1 个负责普通名字,其余 6 个是 mDNS(local 与链路本地反向域)。</p>'),
     ('只问 A 记录', '<p>没有可用的 IPv6,配置标志是 Request A records:即使要求 IPv4+IPv6,线上也只有 A 查询。</p>'),
     ('搜索域', '<p>单标签名字先加搜索域 lan 问一次,NXDOMAIN 后再问不带后缀的裸名字。</p>'),
     ('/etc/hosts', '<p>localhost 等条目不发 DNS 包;自定义条目是否生效没有测。</p>'),
     ('.local 与 mDNS', '<p>.local 名字向 224.0.0.251 发多播查询,查不到要等 5 秒超时。</p>')],
    steps,
    [ENV_W + '。抓包只保留 UDP 53 里含测试标签的 DNS 包和本机自己发出的 mDNS 包,不保留局域网里其它设备的任何流量(第一次抓包带进了其它设备的名字和地址,已丢弃重做);第四节没有 root,不能修改 /etc/hosts',
     '没有验证:/etc/hosts 里自定义条目是否生效;多个名字服务器之间的故障切换(第一个服务器不响应时何时换第二个);ndots 规则(macOS 的多标签名字是否也先加搜索域);作用域查询(scoped)的解析器;DNS-SD / Bonjour 服务发现;Python 的 getaddrinfo 与 dscacheutil / dig 走的路径差别'],
    '存根解析器')
